import pytest
from units import fahrenheit_to_celsius, celsius_to_fahrenheit


class TestFahrenheitToCelsius:
    @pytest.mark.parametrize(
        "fahrenheit, expected",
        [
            (32.0, 0.0),
            (212.0, 100.0),
            (98.6, 37.0),
            (0.0, -17.8),
            (100.0, 37.8),
        ],
    )
    def test_fahrenheit_to_celsius(self, fahrenheit, expected):
        assert fahrenheit_to_celsius(fahrenheit) == expected

    def test_fahrenheit_to_celsius_rounding(self):
        # Test that the result is rounded to one decimal place
        assert fahrenheit_to_celsius(33.0) == 0.6
        assert fahrenheit_to_celsius(32.5) == 0.3


class TestCelsiusToFahrenheit:
    @pytest.mark.parametrize(
        "celsius, expected",
        [
            (0.0, 32.0),
            (100.0, 212.0),
            (37.0, 98.6),
            (-17.8, 0.0),
            (37.8, 100.0),
        ],
    )
    def test_celsius_to_fahrenheit(self, celsius, expected):
        assert celsius_to_fahrenheit(celsius) == expected

    def test_celsius_to_fahrenheit_rounding(self):
        # Test that the result is rounded to one decimal place
        assert celsius_to_fahrenheit(0.6) == 33.0
        assert celsius_to_fahrenheit(0.3) == 32.5


if __name__ == "__main__":
    pytest.main([__file__, "-v"])

