import pytest
from wordfreq import text_word_frequency_analysis

def test_empty_text():
    assert text_word_frequency_analysis("", 3) == []

def test_single_word():
    assert text_word_frequency_analysis("hello", 3) == [("hello", 1)]

def test_multiple_words():
    assert text_word_frequency_analysis("hello world hello", 3) == [("hello", 2), ("world", 1)]

def test_case_insensitive():
    assert text_word_frequency_analysis("Hello HELLO hello", 3) == [("hello", 3)]

def test_punctuation():
    assert text_word_frequency_analysis("hello, world! hello.", 3) == [("hello", 2), ("world", 1)]

def test_apostrophes():
    assert text_word_frequency_analysis("don't stop", 3) == [("don't", 1), ("stop", 1)]

def test_ties_sorted_alphabetically():
    assert text_word_frequency_analysis("zebra apple banana apple", 3) == [("apple", 2), ("banana", 1), ("zebra", 1)]

def test_n_larger_than_unique_words():
    assert text_word_frequency_analysis("a b c", 5) == [("a", 1), ("b", 1), ("c", 1)]

def test_n_zero():
    assert text_word_frequency_analysis("hello world", 0) == []

@pytest.mark.parametrize("text,n,expected", [
    ("a a a b b c", 2, [("a", 3), ("b", 2)]),
    ("x y z x y x", 3, [("x", 3), ("y", 2), ("z", 1)]),
    ("hello world hello world", 2, [("hello", 2), ("world", 2)]),
])
def test_parametrized_cases(text, n, expected):
    assert text_word_frequency_analysis(text, n) == expected
